import {BleManager,Device} from 'react-native-ble-plx';
const mgr=new BleManager();
export function scanBle(onFound:(d:Device)=>void){
  const seen=new Set<string>();
  mgr.startDeviceScan(null,null,(err,d)=>{if(err||!d)return;if(seen.has(d.id))return;seen.add(d.id);onFound(d);});
  setTimeout(()=>mgr.stopDeviceScan(),{{scan_seconds}}*1000);}
